package pe.edu.upeu.casaonada.pago.api;
import pe.edu.upeu.casaonada.pago.dto.*; import pe.edu.upeu.casaonada.pago.service.PagoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1/pagos") public class PagoController { private final PagoService s; public PagoController(PagoService s){this.s=s;} @PostMapping public ResponseEntity<PagoResponse> crear(@RequestHeader(value="X-Idempotency-Key",required=false) String key,@Valid @RequestBody PagoRequest r){var x=s.crear(r,key);return ResponseEntity.created(URI.create("/api/v1/pagos/"+x.id())).body(x);} @GetMapping public List<PagoResponse> listar(){return s.listar();} @GetMapping("/{id}") public PagoResponse buscar(@PathVariable Long id){return s.buscar(id);} }
